import { Component } from '@angular/core';
import { MisCompras } from 'src/app/models/mis-compras';
import { Usuario } from 'src/app/models/usuario';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-buscador',
  templateUrl: './buscador.component.html',
  styleUrls: ['./buscador.component.css']
})
export class BuscadorComponent {

  public usuario: Usuario[] = [];
  public compras: MisCompras[] = [];
  public cantidad : number = 0;
  public nombreProducto : string = "";

  constructor(public misComprasService: MisComprasService, public usuarioService: UsuarioService){}
*
  recogerProducto(){

    this.usuarioService.getUsuarios().subscribe(
      (res : any) =>{
        this.usuario = res;

        for(let usu of this.usuario){

          this.misComprasService.obtenerComprasUsuario(usu.email).subscribe(
            (res : any) =>{
              this.compras = res;

              this.compras.forEach( compra =>{
                  compra.productos.forEach( prod =>{
                    if(prod.nombreProd.toLowerCase() === this.nombreProducto.toLowerCase()){
                      this.cantidad += this.cantidad + 1;
                    }
                  })
              })

            }
          )

        }

      }
    )

  }

}
<div>
  <input type="text" [(ngModel)]="nombreProducto">
  <button (click)="recogerProducto()"> Recoger cantidad </button>
  La cantidad de ese producto es: {{cantidad}}
</div>
